    // 총 카운트 계산
    var countQuery = queryFactory.select(style.count())
            .from(style)
            .leftJoin(style.profile, profile)
            .where(profile.id.eq(profileId));

    return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
